export { Router, useRouter, withRouter } from 'next/router.js';
import NextLink from 'next/link.js';
import NextHead from 'next/head.js';

/**
 * This file is exposed by the /router entrypoint, and helps ensure that other
 * packages import the same instance of next's router.
 */
// the next modules are CJS with `.default` exports so:
// - in Node ESM, they will be on `.default` from the default export
// - in Next proper/moduleResolution: bundler, they will be on the default export itself
// we need to handle both cases and type it explicitly not relying on the default export
const Link = 'default' in NextLink ? NextLink.default : NextLink;
const Head = 'default' in NextHead ? NextHead.default : NextHead;

export { Head, Link };
